<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Waybill {{ $shipment->tracking_number }}</title><style>body{font:14px Arial,sans-serif;color:#17334b;background:#eef1f4;margin:0;padding:35px}.sheet{max-width:760px;margin:auto;background:#fff;padding:45px;border:1px solid #d9e1e7}header{display:flex;justify-content:space-between;border-bottom:3px solid #17334b;padding-bottom:25px}h1{font-size:28px;margin:0}h2{font-size:25px;margin:30px 0 8px}h3{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#8997a3}p{line-height:1.8;margin:4px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;border-bottom:1px solid #dde4ea;padding:20px 0}.notice{font-size:11px;color:#8a98a3;margin-top:30px}.toolbar{max-width:850px;margin:0 auto 20px;display:flex;justify-content:space-between}button{background:#17334b;color:white;padding:12px 20px;border:0;border-radius:4px;cursor:pointer}a{color:#17334b}@media print{body{background:white;padding:0}.sheet{border:0;max-width:none}.toolbar{display:none}a{display:none}}</style></head><body><div class="toolbar"><a href="{{ route('shipments.show',$shipment) }}">← Back to shipment</a><button onclick="window.print()">Print waybill</button></div><main class="sheet"><header><h1>ShipFast.</h1><span>INTERNAL WAYBILL<br>{{ ucfirst($shipment->service_type) }} · {{ strtoupper($shipment->status) }}</span></header><h2>{{ $shipment->tracking_number }}</h2><p>Booking date {{ $shipment->created_at->format('M d, Y') }}</p><div class="grid">@foreach(['origin'=>'From','destination'=>'To'] as $key=>$label)@php($person=$key==='origin'?'sender':'recipient')<section><h3>{{ $label }}</h3><p><strong>{{ $shipment->{$person.'_name'}?:'Name not provided' }}</strong></p><p>{{ $shipment->{$key.'_address'}?:'Address not provided' }}</p><p>{{ $shipment->{$key.'_city'} }}, {{ $shipment->{$key.'_country'} }} {{ $shipment->{$key.'_postal_code'} }}</p><p>{{ $shipment->{$person.'_phone'} }}</p></section>@endforeach</div><div class="grid"><section><h3>Parcel</h3><p>{{ $shipment->contents_description?:'Description not provided' }}</p><p>{{ $shipment->weight }} kg · {{ $shipment->dimensions?:'No dimensions recorded' }}</p><p>{{ $shipment->signature_required?'Signature required':'Standard confirmation' }}</p></section><section><h3>Shipping estimate</h3><p>USD {{ number_format($shipment->shipping_cost,2) }}</p><p>Estimated arrival {{ $shipment->estimated_delivery?->format('M d, Y') }}</p><p>Duties and taxes excluded.</p></section></div><p class="notice">Internal shipment reference only. This is not a carrier-issued shipping label, proof of postage, customs invoice or customs declaration. Confirm collection and cross-border documents separately.</p></main></body></html>